      const finish = async () => {
        const newTitle = input.value.trim();
        if (newTitle && newTitle !== currentTitle) {
          try {
            await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { title: newTitle } });
            showMessage("Todo renamed", "success");
          } catch (err) {
            if (err instanceof ApiError) {
              showMessage(err.message, "error");
            } else {
              showMessage("Failed to rename todo", "error");
            }
          }
        }
        loadTodos();
      };

      input.addEventListener("blur", finish);
      input.addEventListener("keydown", (e) => {
        if (e.key === "Enter") finish();
        if (e.key === "Escape") loadTodos();
      });
    }

    async function deleteTodo(id) {
      if (!confirm("Delete this todo?")) return;
      try {
        await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
        showMessage("Todo deleted", "success");
        await loadTodos();
      } catch (err) {
        if (err instanceof ApiError) {
          showMessage(err.message, "error");
        } else {
          showMessage("Failed to delete todo", "error");
        }
      }
    }

    await loadUser();
    await loadTodos();
  </script>
</body>
</html>
